using Beep.OilandGas.Models.Data.Accounting;
using Beep.OilandGas.Models.Data.Company;
namespace Beep.OilandGas.Web.Services;
public sealed partial class AccountingServiceClient
{
    private const string BookRoute="api/accounting/traditional/gl/company-accounts/books";
    public async Task<CompanyLedgerBookReview> GetCompanyLedgerBooksAsync(){var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original company/account.");var result=await _apiClient.GetAsync<CompanyLedgerBookReview>(BookRoute) ??throw new InvalidOperationException("The complete company book configuration is unavailable.");if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during book review.");result.Require(snapshot.Selection.Scope,snapshot.Selection.UserId);return CompanyInventorySourceReview.Copy(result);}
    public async Task<CompanyLedgerBookConfigurationReview> GetCompanyLedgerBookConfigurationReviewAsync(){var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original company/account.");var result=await _apiClient.GetAsync<CompanyLedgerBookConfigurationReview>(BookRoute+"/configuration-review") ??throw new InvalidOperationException("The original company book management source is unavailable.");if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during book management review.");result.Require(snapshot.Selection.Scope,snapshot.Selection.UserId);return CompanyInventorySourceReview.Copy(result);}
    public async Task<COMPANY_LEDGER_BOOK> ConfigureCompanyLedgerBookAsync(CompanyLedgerBookConfigurationSubmission submission){submission=CompanyInventorySourceReview.Copy(submission);submission.Command.Require();var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null || snapshot.Selection.Scope!=submission.Command.Company || snapshot.Selection.UserId!=submission.Command.ActorUserId)throw new InvalidOperationException("Return to the original book company/account.");var result=await _apiClient.PostAsync<CompanyLedgerBookConfigurationSubmission,COMPANY_LEDGER_BOOK>(BookRoute+"/configuration",submission) ??throw new InvalidOperationException("The original book configuration is unconfirmed.");if(snapshot!=_apiClient.CompanySnapshot || CompanyLedgerBookConfigurationProof.Require(result).Command!=submission.Command)throw new InvalidOperationException("The original book command/outcome or company context changed.");return CompanyInventorySourceReview.Copy(result);}
    public async Task<COMPANY_LEDGER_BOOK?> GetCompanyLedgerBookConfigurationAsync(string id){if(!Guid.TryParseExact(id,"N",out var identity) || identity==Guid.Empty || identity.ToString("N")!=id)throw new ArgumentException("The original native book identity is required.");var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original book producer company/account.");var result=await _apiClient.GetAsync<COMPANY_LEDGER_BOOK>(BookRoute+"/configuration/"+Uri.EscapeDataString(id));if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during book recovery.");if(result is null)return null;var command=CompanyLedgerBookConfigurationProof.Require(result).Command;if(command.Company!=snapshot.Selection.Scope || command.ActorUserId!=snapshot.Selection.UserId || command.Id!=id)throw new InvalidOperationException("The private original book configuration belongs to another context.");return CompanyInventorySourceReview.Copy(result);}
}
